# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZIN 12 FARZI: DIŞINDAN (ŞARTLARI) VE İÇİNDEN (RÜKÜNLERİ)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Namazın Dışındaki Farzlar (6 Şart)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• 1) Hadesten Tahâret: Abdest/gusül almak</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">• 2) Necâsetten Tahâret: Beden, elbise ve</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">namaz kılınacak yerin temiz olması</text>\n  <text x="180" y="158" text-anchor="middle" font-size="11" fill="#1e3a8a">• 3) Setr-i Avret: Örtünmesi gereken yerleri örtmek</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">• 4) İstikbâl-i Kıble: Kâbe\'ye (kıbleye) yönelmek</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11" fill="#1e3a8a">• 5) Vakit: Namaz vaktinin girmiş olması</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#1e3a8a">• 6) Niyet: Kılınacak namaza kalben niyet etmek</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Namazın İçindeki Farzlar (6 Rükün)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" fill="#14532d">• 1) İftitah (Başlama) Tekbiri: «Allâhü Ekber»</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#14532d">• 2) Kıyam: Namazda ayakta durmak</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" fill="#14532d">• 3) Kıraat: Ayakta Kur\'an\'dan ayet/sure okumak</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#14532d">• 4) Rükû: Elleri dizlere koyarak eğilmek</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#14532d">• 5) Secde: Alın, burun, eller, dizler ve ayak</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11" fill="#14532d">parmaklarını yere koyarak iki kez kapanmak</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#14532d">• 6) Ka\'de-i Ahîre: Son oturuş (Tahiyyat süresi)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BEŞ VAKİT NAMAZIN REKÂT SAYILARI VE KILINIŞ SIRASI (TOPLAM 40 REKÂT)</text>\n  <rect x="16" y="48" width="128" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="80" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Sabah (4 Rekât)</text>\n  <text x="80" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">• 2 Rekât Sünnet</text>\n  <text x="80" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• 2 Rekât Farz</text>\n  <text x="80" y="160" text-anchor="middle" font-size="10.5" fill="#475569">İmsak vaktiyle başlar,</text>\n  <text x="80" y="176" text-anchor="middle" font-size="10.5" fill="#475569">güneş doğunca biter.</text>\n  <text x="80" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Toplam: 4 Rekât</text>\n\n  <rect x="151" y="48" width="128" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="215" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Öğle (10 Rekât)</text>\n  <text x="215" y="100" text-anchor="middle" font-size="11" fill="#14532d">• 4 İlk Sünnet</text>\n  <text x="215" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• 4 Rekât Farz</text>\n  <text x="215" y="144" text-anchor="middle" font-size="11" fill="#14532d">• 2 Son Sünnet</text>\n  <text x="215" y="174" text-anchor="middle" font-size="10.5" fill="#475569">Cuma günü öğle yerine</text>\n  <text x="215" y="190" text-anchor="middle" font-size="10.5" fill="#475569">Cuma namazı kılınır.</text>\n  <text x="215" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Toplam: 10 Rekât</text>\n\n  <rect x="286" y="48" width="128" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. İkindi (8 Rekât)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#713f12">• 4 Rekât Sünnet</text>\n  <text x="350" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">• 4 Rekât Farz</text>\n  <text x="350" y="160" text-anchor="middle" font-size="10.5" fill="#475569">Son sünneti yoktur;</text>\n  <text x="350" y="176" text-anchor="middle" font-size="10.5" fill="#475569">güneş batana dek sürer.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Toplam: 8 Rekât</text>\n\n  <rect x="421" y="48" width="128" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="485" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">4. Akşam (5 Rekât)</text>\n  <text x="485" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">• 3 Rekât Farz</text>\n  <text x="485" y="126" text-anchor="middle" font-size="11" fill="#9d174d">• 2 Rekât Sünnet</text>\n  <text x="485" y="160" text-anchor="middle" font-size="10.5" fill="#475569">Önce farzı kılınan</text>\n  <text x="485" y="176" text-anchor="middle" font-size="10.5" fill="#475569">tek vakit namazıdır.</text>\n  <text x="485" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Toplam: 5 Rekât</text>\n\n  <rect x="556" y="48" width="128" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="620" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">5. Yatsı (13 Rekât)</text>\n  <text x="620" y="98" text-anchor="middle" font-size="10.5" fill="#581c87">• 4 İlk Sünnet</text>\n  <text x="620" y="118" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">• 4 Rekât Farz</text>\n  <text x="620" y="138" text-anchor="middle" font-size="10.5" fill="#581c87">• 2 Son Sünnet</text>\n  <text x="620" y="160" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">+ 3 Rekât Vitir (Vacip)</text>\n  <text x="620" y="182" text-anchor="middle" font-size="10" fill="#475569">(Kunut duaları okunur)</text>\n  <text x="620" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Toplam: 10+3 = 13</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZIN BİREYSEL-TOPLUMSAL KAZANIMLARI VE EZAN-KAMET</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Namazın Önemi ve Kazanımları</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#155e75">• «Dinin direği» ve «müminin miracıdır».</text>\n  <text x="182" y="124" text-anchor="middle" font-size="11" fill="#155e75">• Ankebût 45: «Şüphesiz namaz, insanı</text>\n  <text x="182" y="140" text-anchor="middle" font-size="11" fill="#155e75">hayâsızlıktan ve kötülükten alıkoyar.»</text>\n  <text x="182" y="164" text-anchor="middle" font-size="11" fill="#155e75">• Günde 5 kez temizlik ve zaman disiplini</text>\n  <text x="182" y="182" text-anchor="middle" font-size="11" fill="#155e75">kazandırır, ruhsal huzur verir.</text>\n  <text x="182" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• Cemaatle namaz birlik ve kardeşliği artırır.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Ezan, Kamet ve Cemaat</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#9a3412">• Ezan: Namaz vaktinin girdiğini bildiren</text>\n  <text x="517" y="118" text-anchor="middle" font-size="11" fill="#9a3412">çağrıdır (İlk müezzin: Hz. Bilâl-i Habeşî).</text>\n  <text x="517" y="142" text-anchor="middle" font-size="11" fill="#9a3412">• Kamet: Farz namazlara başlarken okunur;</text>\n  <text x="517" y="158" text-anchor="middle" font-size="11" fill="#9a3412">ezandan farkı «Kad kâmeti\'s-salâh» sözüdür.</text>\n  <text x="517" y="182" text-anchor="middle" font-size="11" fill="#9a3412">• Vacip Namazlar: Vitir ve Bayram namazları.</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">• Farz-ı Kifâye: Cenaze namazı (Rükû/secde yok).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
